def top_k_counts(words: list[str], k: int) -> list[tuple[str, int]]:
    if k <= 0:
        return []
    first_occurrence = {}
    counts = {}
    for idx, w in enumerate(words):
        key = w.lower()
        if key not in first_occurrence:
            first_occurrence[key] = idx
            counts[key] = {"word": w, "count": 0}
        counts[key]["count"] += 1

    items = [
        (counts[key]["word"], counts[key]["count"], first_occurrence[key])
        for key in counts
    ]
    items.sort(key=lambda x: (-x[1], x[2]))
    return [(word, cnt) for word, cnt, _ in items[:k]]
