import json
import math

def parse_jsonl_metrics(lines: list[str]) -> dict:
    invalid_count = 0
    service_data = {}

    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            invalid_count += 1
            continue

        if not isinstance(obj.get("service"), str):
            invalid_count += 1
            continue
        if not isinstance(obj.get("latency_ms"), (int, float)):
            invalid_count += 1
            continue
        if not isinstance(obj.get("status"), (int, float)):
            invalid_count += 1
            continue

        service = obj["service"]
        latency = obj["latency_ms"]
        status = obj["status"]

        if service not in service_data:
            service_data[service] = {"latencies": [], "ok_count": 0, "total": 0}
        svc = service_data[service]
        svc["latencies"].append(latency)
        svc["total"] += 1
        if 200 <= status < 300:
            svc["ok_count"] += 1

    result = {"invalid": invalid_count}
    for service in sorted(service_data):
        data = service_data[service]
        count = data["total"]
        ok_rate = data["ok_count"] / count if count else 0.0
        latencies = sorted(data["latencies"])
        n = len(latencies)
        if n == 0:
            p95 = None
        else:
            idx = math.ceil(0.95 * n) - 1
            p95 = latencies[idx]
        result[service] = {
            "count": count,
            "ok_rate": ok_rate,
            "p95_latency_ms": p95,
        }
    return result
