from collections import OrderedDict

def streaming_group_sum(rows):
    class G:
        def __init__(self):
            self.invalid_count = 0
            self._data = OrderedDict()
        def __iter__(self):
            for k, v in self._data.items():
                yield (k, v)
    g = G()
    for row in rows:
        try:
            if not (isinstance(row, (list, tuple)) and len(row) == 3):
                raise ValueError
            _, key, val = row
            num = float(val)
            if key not in g._data:
                g._data[key] = 0.0
            g._data[key] += num
        except Exception:
            g.invalid_count += 1
    return g

import time

def retry_call(fn, attempts, retry_if, *, base_delay=0.01, sleep=time.sleep):
    if attempts <= 0:
        raise ValueError("attempts must be >0")
    for i in range(attempts):
        if i > 0:
            sleep(base_delay * 2**(i - 1))
        try:
            return fn()
        except Exception as e:
            if not retry_if(e):
                raise
            if i == attempts - 1:
                raise
    raise RuntimeError("unreachable")

