import copy

def apply_patch_ops(document: dict, operations) -> dict:
    """
    Apply a list of patch operations to a deep copy of the given document.
    Operations:
        - 'set': set a value at a dotted path (creates intermediate dicts)
        - 'delete': delete a value at a dotted path (no error if path missing)
        - 'increment': add a numeric value to a numeric value at a dotted path
    If any operation fails, the original document is returned unchanged.
    """
    original = copy.deepcopy(document)   # for rollback
    work = copy.deepcopy(document)       # mutable working copy

    def path_exists(doc, path):
        """Check if a dotted path exists in the document."""
        cur = doc
        for key in path.split('.'):
            if isinstance(cur, dict) and key in cur:
                cur = cur[key]
            else:
                return False
        return True

    try:
        for op, path, value in operations:
            keys = path.split('.')
            if op == 'set':
                if len(keys) == 1:
                    # top‑level key
                    work[keys[0]] = value
                else:
                    # ensure parent path exists (create intermediate dicts)
                    cur = work
                    for k in keys[:-1]:
                        if k not in cur:
                            cur[k] = {}
                        cur = cur[k]
                    cur[keys[-1]] = value

            elif op == 'delete':
                if not path_exists(work, path):
                    continue  # path does not exist → no‑op
                if len(keys) == 1:
                    work.pop(keys[0], None)
                else:
                    cur = work
                    for k in keys[:-1]:
                        cur = cur[k]
                    cur.pop(keys[-1], None)

            elif op == 'increment':
                if not path_exists(work, path):
                    raise KeyError(f"Path '{path}' does not exist for increment")
                if len(keys) == 1:
                    cur = work[keys[0]]
                else:
                    cur = work
                    for k in keys[:-1]:
                        cur = cur[k]
                if not isinstance(cur, (int, float)):
                    raise TypeError(f"Value at '{path}' must be numeric for increment")
                cur = cur + value
                # write back
                if len(keys) == 1:
                    work[keys[0]] = cur
                else:
                    cur_parent = work
                    for k in keys[:-1]:
                        cur_parent = cur_parent[k]
                    cur_parent[keys[-1]] = cur

            else:
                raise ValueError(f"Unsupported operation '{op}'")

        return work

    except Exception:
        # Any failure → rollback by returning the untouched original copy
        return original
