from collections import OrderedDict
from threading import RLock

class TTLCache:
    def __init__(self, maxsize: int, ttl: float, *, clock=time.time):
        if maxsize <= 0:
            raise ValueError("maxsize must be > 0")
        if ttl < 0:
            raise ValueError("ttl must be >= 0")
        self._maxsize = maxsize
        self._ttl = ttl
        self._clock = clock
        self._data = OrderedDict()          # key -> (value, expiry)
        self._lock = RLock()

    def get(self, key, default=None):
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return default
            value, expiry = entry
            if expiry <= self._clock():
                del self._data[key]
                return default
            self._data.move_to_end(key)
            return value

    def set(self, key, value):
        with self._lock:
            expiry = self._clock() + self._ttl
            if key in self._data:
                self._data.move_to_end(key)
            self._data[key] = (value, expiry)
            self._evict_if_needed()

    def delete(self, key):
        with self._lock:
            self._data.pop(key, None)

    def __len__(self):
        with self._lock:
            return len(self._data)

    def _evict_if_needed(self):
        while len(self._data) > self._maxsize:
            # pop the least‑recently used item
            try:
                key, (_, expiry) = self._data.popitem(last=False)
            except KeyError:
                break  # no items to evict
            # If the item is already expired, it has been removed by get;
            # we simply continue until size constraint is satisfied.
