import threading

class TTLCache:
    def __init__(self, ttl):
        self.ttl = ttl
        self._store = {}  # key -> (value, expires_at)
        self._lock = threading.RLock()

    def get(self, key):
        with self._lock:
            entry = self._store.get(key)
            if entry is None:
                return None
            value, expires_at = entry
            if expires_at > time.time():
                return value
            else:
                del self._store[key]
                return None

    def set(self, key, value):
        with self._lock:
            expires_at = time.time() + self.ttl
            self._store[key] = (value, expires_at)

    def delete(self, key):
        with self._lock:
            self._store.pop(key, None)

    def __len__(self):
        with self._lock:
            now = time.time()
            cnt = 0
            for k, (_, exp) in self._store.items():
                if exp > now:
                    cnt += 1
            return cnt


class SingleFlightTTLCache:
    def __init__(self, ttl):
        self._cache = TTLCache(ttl)
        self._lock = threading.RLock()
        self._pending = {}  # key -> {'lock': Lock, 'event': Event, 'result': value, 'exception': exception}

    def get(self, key):
        value = self._cache.get(key)
        if value is not None:
            return value

        with self._lock:
            if key not in self._pending:
                lock = threading.Lock()
                event = threading.Event()
                self._pending[key] = {'lock': lock, 'event': event, 'result': None, 'exception': None}
            event = self._pending[key]['event']

        event.wait()

        with self._lock:
            entry = self._pending[key]
            if entry['exception'] is not None:
                raise entry['exception']
            return entry['result']

    def get_or_load(self, key, loader):
        value = self._cache.get(key)
        if value is not None:
            return value

        with self._lock:
            if key not in self._pending:
                lock = threading.Lock()
                event = threading.Event()
                self._pending[key] = {'lock': lock, 'event': event, 'result': None, 'exception': None}
            else:
                lock = self._pending[key]['lock']
                event = self._pending[key]['event']

        lock.acquire()
        try:
            value = self._cache.get(key)
            if value is not None:
                event.set()
                return value

            try:
                result = loader(key)
            except Exception as e:
                with self._lock:
                    self._pending[key]['exception'] = e
                raise e

            self._cache.set(key, result)
            with self._lock:
                self._pending[key]['result'] = result
            event.set()
            return result
        finally:
            lock.release()

    def set(self, key, value):
        self._cache.set(key, value)

    def delete(self, key):
        self._cache.delete(key)

    def __len__(self):
        return len(self._cache)

