import asyncio
from typing import Awaitable, Iterable, List, Tuple, Union

async def run_with_deadline(
    coros: Iterable[Awaitable],
    limit: int,
    timeout: float,
) -> List[Tuple[str, Union[int, float, str, Exception]]]:
    coros = list(coros)
    n = len(coros)
    results: List[Tuple[str, Union[int, float, str, Exception]]] = [None] * n
    result_map = {}

    sem = asyncio.Semaphore(limit)

    async def runner(idx: int, coro: Awaitable):
        try:
            value = await coro
            result_map[idx] = ("ok", value)
        except asyncio.CancelledError:
            result_map[idx] = ("cancelled", None)
        except Exception as exc:
            result_map[idx] = ("error", exc)

    tasks = [
        asyncio.create_task(runner(i, coro))
        for i, coro in enumerate(coros)
    ]

    try:
        await asyncio.wait_for(asyncio.gather(*tasks), timeout=timeout)
    except asyncio.TimeoutError:
        for t in tasks:
            t.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)

    for i in range(n):
        results[i] = result_map.get(i, ("cancelled", None))

    return results
