import threading
from collections import deque

class BoundedQueue:
    def __init__(self, capacity):
        self._cap = capacity
        self._q = deque()
        self._cond = threading.Condition()
        self._closed = False

    def put(self, item):
        with self._cond:
            if self._closed:
                raise RuntimeError("put on closed queue")
            while len(self._q) >= self._cap:
                self._cond.wait()
            self._q.append(item)
            self._cond.notify_all()

    def get(self):
        with self._cond:
            if self._closed and not self._q:
                raise RuntimeError("get on closed empty queue")
            while len(self._q) == 0:
                self._cond.wait()
            item = self._q.popleft()
            self._cond.notify_all()
            return item

    def close(self):
        with self._cond:
            if not self._closed:
                self._closed = True
                self._cond.notify_all()
