import copy

class VersionedStore:
    def __init__(self):
        self._lock = threading.RLock()
        self._data = {}  # key -> {'version': int, 'value': object}

    def read(self, key):
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                raise KeyError(key)
            return copy.deepcopy(entry['value'])

    def compare_and_set(self, key, expected_version, value):
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return False
            if entry['version'] != expected_version:
                return False
            entry['version'] += 1
            entry['value'] = value
            return True

    def delete(self, key, expected_version):
        with self._lock:
            entry = self._data.get(key)
            if entry is None:
                return False
            if entry['version'] != expected_version:
                return False
            del self._data[key]
            return True

    def snapshot(self):
        with self._lock:
            snap = {}
            for k, v in self._data.items():
                snap[k] = copy.deepcopy(v['value'])
            return snap

import math

def is_multiply_prime(a):
    """Return True if a is the product of exactly three prime numbers (counting multiplicities), otherwise False."""
    if a < 2:
        return False
    count = 0
    n = a
    p = 2
    while p * p <= n:
        while n % p == 0:
            count += 1
            n //= p
            if count > 3:
                return False
        p += 1 if p == 2 else 2
    if n > 1:
        count += 1
    return count == 3

